  1→import { useState, useCallback } from 'react';
  2→import { Modal } from '../ui/Modal';
  3→import { useUploadStore } from '../../stores/upload.store';
  4→import type { PendingReplacement } from '../../stores/upload.store';
  5→import { useFileOperations } from '../../hooks/useFileOperations';
  6→import { unpinFromIpfs } from '../../lib/api/ipfs';
  7→import { useQuotaStore } from '../../stores/quota.store';
  8→import '../../styles/dialogs.css';
  9→
 10→type ReplaceFileDialogProps = {
 11→  replacements: PendingReplacement[];
 12→  onComplete: () => void;
 13→};
 14→
 15→/**
 16→ * Dialog shown when uploaded files have names that already exist in the folder.
 17→ * Offers Replace (creates version) or Skip (discards the upload) for each file.
 18→ */
 19→export function ReplaceFileDialog({ replacements, onComplete }: ReplaceFileDialogProps) {
 20→  const { updateFile } = useFileOperations();
 21→  const [currentIndex, setCurrentIndex] = useState(0);
 22→  const [isLoading, setIsLoading] = useState(false);
 23→
 24→  const current = replacements[currentIndex];
 25→  const isLast = currentIndex >= replacements.length - 1;
 26→
 27→  const advance = useCallback(() => {
 28→    if (isLast) {
 29→      useUploadStore.getState().clearPendingReplacements();
 30→      onComplete();
 31→    } else {
 32→      setCurrentIndex((i) => i + 1);
 33→    }
 34→  }, [isLast, onComplete]);
 35→
 36→  const handleReplace = useCallback(async () => {
 37→    if (!current || isLoading) return;
 38→    setIsLoading(true);
 39→    try {
 40→      await updateFile(current.parentId, {
 41→        fileId: current.fileId,
 42→        newCid: current.encryptedData.cid,
 43→        newFileKeyEncrypted: current.encryptedData.wrappedKey,
 44→        newFileIv: current.encryptedData.iv,
 45→        newSize: current.encryptedData.size,
 46→        forceVersion: true,
 47→      });
 48→      advance();
 49→    } catch (err) {
 50→      console.error('[replace] Failed to replace file:', err);
 51→    } finally {
 52→      setIsLoading(false);
 53→    }
 54→  }, [current, isLoading, updateFile, advance]);
